-- Errata reading for M10: Most recent = the last result by event_time (record_id tiebreak), not the worse value of the latest day.
WITH an AS (SELECT DISTINCT patient FROM records WHERE stream='conditions' AND (lower(json_extract(payload,'$.description')) LIKE '%anemia%' OR lower(json_extract(payload,'$.description')) LIKE '%anaemia%' OR json_extract(payload,'$.snomed')='271737000' OR substr(coalesce(json_extract(payload,'$.icd10'),''),1,3) BETWEEN 'D50' AND 'D64')), lab AS (SELECT patient, json_extract(payload,'$.value') v, row_number() OVER (PARTITION BY patient ORDER BY json_extract(payload,'$.event_date') DESC, json_extract(payload,'$.event_time') DESC, json_extract(payload,'$.record_id') DESC) rn FROM records WHERE stream='labs' AND json_extract(payload,'$.name') IN ('Hemoglobin','Hgb') AND json_extract(payload,'$.event_date') IS NOT NULL AND typeof(json_extract(payload,'$.value')) IN ('integer','real') AND coalesce(json_extract(payload,'$.result_status'),'')<>'cancelled'), last AS (SELECT patient, v FROM lab WHERE rn=1) SELECT COUNT(*) AS count FROM last WHERE v < 11.0 AND patient IN (SELECT patient FROM an);
